-- Rollback for db/scripts/seed_equipment_catalog_1_80.sql
--
-- Removes only the content generated by that seed:
-- - items with code prefix SET_
-- - related rows in public.equipments
-- - canonical DragonKi sets and their bonuses
--
-- It does not drop the shared schema objects created by migrations.

DO $$
DECLARE
    v_items_seq TEXT;
    v_equipments_seq TEXT;
    v_sets_seq TEXT;
    v_set_bonuses_seq TEXT;
BEGIN
    UPDATE public.player_equipments pe
       SET weapon_inventory_item_id = NULL
     WHERE weapon_inventory_item_id IN (
         SELECT ii.id
           FROM public.inventory_items ii
           JOIN public.items i ON i.id = ii.item_id
          WHERE i.code LIKE 'SET\_%' ESCAPE '\'
     );

    UPDATE public.player_equipments pe
       SET armor_inventory_item_id = NULL
     WHERE armor_inventory_item_id IN (
         SELECT ii.id
           FROM public.inventory_items ii
           JOIN public.items i ON i.id = ii.item_id
          WHERE i.code LIKE 'SET\_%' ESCAPE '\'
     );

    UPDATE public.player_equipments pe
       SET gloves_inventory_item_id = NULL
     WHERE gloves_inventory_item_id IN (
         SELECT ii.id
           FROM public.inventory_items ii
           JOIN public.items i ON i.id = ii.item_id
          WHERE i.code LIKE 'SET\_%' ESCAPE '\'
     );

    UPDATE public.player_equipments pe
       SET helmet_inventory_item_id = NULL
     WHERE helmet_inventory_item_id IN (
         SELECT ii.id
           FROM public.inventory_items ii
           JOIN public.items i ON i.id = ii.item_id
          WHERE i.code LIKE 'SET\_%' ESCAPE '\'
     );

    UPDATE public.player_equipments pe
       SET boots_inventory_item_id = NULL
     WHERE boots_inventory_item_id IN (
         SELECT ii.id
           FROM public.inventory_items ii
           JOIN public.items i ON i.id = ii.item_id
          WHERE i.code LIKE 'SET\_%' ESCAPE '\'
     );

    UPDATE public.player_equipments pe
       SET ring_inventory_item_id = NULL
     WHERE ring_inventory_item_id IN (
         SELECT ii.id
           FROM public.inventory_items ii
           JOIN public.items i ON i.id = ii.item_id
          WHERE i.code LIKE 'SET\_%' ESCAPE '\'
     );

    UPDATE public.player_equipments pe
       SET amulet_inventory_item_id = NULL
     WHERE amulet_inventory_item_id IN (
         SELECT ii.id
           FROM public.inventory_items ii
           JOIN public.items i ON i.id = ii.item_id
          WHERE i.code LIKE 'SET\_%' ESCAPE '\'
     );

    UPDATE public.player_equipments pe
       SET accessory_inventory_item_id = NULL
     WHERE accessory_inventory_item_id IN (
         SELECT ii.id
           FROM public.inventory_items ii
           JOIN public.items i ON i.id = ii.item_id
          WHERE i.code LIKE 'SET\_%' ESCAPE '\'
     );

    DELETE FROM public.inventory_items
     WHERE item_id IN (
         SELECT id
           FROM public.items
          WHERE code LIKE 'SET\_%' ESCAPE '\'
     );

    UPDATE public.items
       SET equipment_id = NULL
     WHERE code LIKE 'SET\_%' ESCAPE '\';

    DELETE FROM public.equipments
     WHERE item_id IN (
         SELECT id
           FROM public.items
          WHERE code LIKE 'SET\_%' ESCAPE '\'
     );

    DELETE FROM public.items
     WHERE code LIKE 'SET\_%' ESCAPE '\';

    DELETE FROM public.equipment_set_bonuses
     WHERE set_id IN (
         SELECT id
           FROM public.equipment_sets
          WHERE name IN (
              'Set Tempestade',
              'Set Guardiao da Terra',
              'Set Vulcanico'
          )
     );

    DELETE FROM public.equipment_sets
     WHERE name IN (
         'Set Tempestade',
         'Set Guardiao da Terra',
         'Set Vulcanico'
     );

    v_items_seq := pg_get_serial_sequence('public.items', 'id');
    IF v_items_seq IS NOT NULL THEN
        EXECUTE format(
            'SELECT setval(%L, COALESCE((SELECT MAX(id) FROM public.items), 0) + 1, false)',
            v_items_seq
        );
    END IF;

    v_equipments_seq := pg_get_serial_sequence('public.equipments', 'id');
    IF v_equipments_seq IS NOT NULL THEN
        EXECUTE format(
            'SELECT setval(%L, COALESCE((SELECT MAX(id) FROM public.equipments), 0) + 1, false)',
            v_equipments_seq
        );
    END IF;

    v_sets_seq := pg_get_serial_sequence('public.equipment_sets', 'id');
    IF v_sets_seq IS NOT NULL THEN
        EXECUTE format(
            'SELECT setval(%L, COALESCE((SELECT MAX(id) FROM public.equipment_sets), 0) + 1, false)',
            v_sets_seq
        );
    END IF;

    v_set_bonuses_seq := pg_get_serial_sequence('public.equipment_set_bonuses', 'id');
    IF v_set_bonuses_seq IS NOT NULL THEN
        EXECUTE format(
            'SELECT setval(%L, COALESCE((SELECT MAX(id) FROM public.equipment_set_bonuses), 0) + 1, false)',
            v_set_bonuses_seq
        );
    END IF;
END $$;
